"use client";

import Image from "next/image";
import TjLink from "@/components/TjLink";
import { useState } from "react";
import type { PostListItem } from "@/lib/api";
import { getCategoryUrlSlugFromWpSlug } from "@/lib/categorySlugs";
import { BLUR_DATA_URL } from "@/lib/constants";

interface ArticleCardProps {
  post: PostListItem;
  variant?: "default" | "hero" | "strip";
  size?: "large" | "medium" | "small";
  /** Imposta priority per le immagini above-the-fold (hero, prime card). */
  priority?: boolean;
}

function formatAbsoluteDate(dateStr: string): string {
  return new Date(dateStr).toLocaleDateString("it-IT", {
    day: "numeric",
    month: "short",
    year: "numeric",
    timeZone: "Europe/Rome",
  });
}

export default function ArticleCard({ post, variant = "default", size, priority }: ArticleCardProps) {
  const [heroImageError, setHeroImageError] = useState(false);
  const categoryUrlSlug = getCategoryUrlSlugFromWpSlug(post.categorySlug);
  const href = `/${categoryUrlSlug}/${post.slug}`;
  const categoryHref = `/${categoryUrlSlug}`;
  const showHeroImage = variant === "hero" && post.imageUrl && !heroImageError;
  const heroSizes =
    size === "large"
      ? "(max-width: 768px) 100vw, (max-width: 1280px) 50vw, 50vw"
      : size === "medium"
        ? "(max-width: 768px) 100vw, (max-width: 1280px) 50vw, 25vw"
        : "(max-width: 768px) 100vw, (max-width: 1280px) 50vw, 25vw";

  if (variant === "strip") {
    return (
      <TjLink href={href} className="group block">
        <div className="relative overflow-hidden rounded-lg aspect-[4/3] bg-content-bg mb-2">
          {post.imageUrl && (
            <Image
              src={post.imageUrl}
              alt={post.imageAlt}
              fill
              className="object-cover transition-transform md:group-hover:scale-105"
              sizes="(max-width: 768px) 50vw, 20vw"
              placeholder="blur"
              blurDataURL={BLUR_DATA_URL}
            loading="lazy"
            fetchPriority="low"
            />
          )}
        </div>
        <h2 className="text-foreground font-semibold text-sm line-clamp-2 group-hover:text-accent transition-colors">
          {post.title}
        </h2>
      </TjLink>
    );
  }

  if (variant === "hero") {
    const titleLines = size === "large" ? 2 : size === "medium" ? 3 : 2;
    const titleSize = size === "large" ? "text-base md:text-xl" : size === "medium" ? "text-sm md:text-base" : "text-xs md:text-sm";
    return (
      <TjLink
        href={href}
        className="group block absolute inset-0 overflow-hidden rounded-lg w-full bg-sidebar-bg lg:min-h-0"
      >
        {showHeroImage ? (
          <Image
            src={post.imageUrl!}
            alt={post.imageAlt}
            fill
            className="object-cover transition-transform md:group-hover:scale-105"
            sizes={heroSizes}
            placeholder="blur"
            blurDataURL={BLUR_DATA_URL}
            priority={priority}
            loading={priority ? "eager" : "lazy"}
            fetchPriority={priority ? "high" : "low"}
            onError={() => setHeroImageError(true)}
          />
        ) : (
          <div className="absolute inset-0 bg-sidebar-bg" aria-hidden />
        )}
        {/* Overlay scuro in basso: titolo sempre leggibile anche con immagine chiara o mancante */}
        <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent pointer-events-none" aria-hidden />
        {/* In basso: label categoria (arancione); sotto, titolo con sfondo nero che segue ogni riga del testo */}
        <div className="absolute bottom-0 left-0 right-0 p-2 md:p-3 max-w-full z-[1]">
          <span className="block bg-accent text-gray-900 text-[10px] md:text-xs font-semibold uppercase tracking-wide px-2 py-0.5 mb-1 w-fit">
            {post.categoryName}
          </span>
          {/* box-decoration-clone: lo sfondo nero viene applicato a ogni riga del testo, non a un contenitore */}
          <span
            className={`block overflow-hidden max-w-full ${titleLines === 2 ? "line-clamp-2" : "line-clamp-3"}`}
            style={{ display: "block" }}
          >
            <span
              className={`inline text-white font-bold ${titleSize} uppercase leading-tight bg-black px-2 py-0.5 md:px-3 md:py-1`}
              style={{ boxDecorationBreak: "clone", WebkitBoxDecorationBreak: "clone" }}
            >
              {post.title}
            </span>
          </span>
        </div>
      </TjLink>
    );
  }

  return (
    <article className="flex flex-col group">
      {/* Stesso motivo di `ArticleCardStatic`: l'`alt` arriva dal CMS e spesso è
          vuoto, lasciando il link immagine senza nome accessibile. */}
      <TjLink
        href={href}
        aria-label={post.title}
        className="block overflow-hidden rounded-lg aspect-[16/10] relative bg-content-bg"
      >
        {post.imageUrl ? (
          <Image
            src={post.imageUrl}
            alt={post.imageAlt}
            fill
            className="object-cover transition-transform md:group-hover:scale-105"
            sizes="(max-width: 768px) 100vw, (max-width: 1280px) 50vw, 33vw"
            placeholder="blur"
            blurDataURL={BLUR_DATA_URL}
            priority={priority}
            loading={priority ? "eager" : "lazy"}
            fetchPriority={priority ? "high" : "low"}
          />
        ) : (
          <div className="absolute inset-0 bg-sidebar-bg" />
        )}
      </TjLink>
      <div className="pt-2">
        <TjLink
          href={categoryHref}
          className="text-accent text-xs font-semibold uppercase tracking-wide hover:underline"
        >
          {post.categoryName}
        </TjLink>
        <TjLink href={href}>
          <h2 className="text-foreground font-bold text-base mt-1 line-clamp-2 min-h-11 hover:text-accent transition-colors">
            {post.title}
          </h2>
        </TjLink>
        <time className="text-muted text-sm mt-1 block" dateTime={post.date}>
          {formatAbsoluteDate(post.date)}
        </time>
      </div>
    </article>
  );
}
