"use client";

import ArticleCard from "./ArticleCard";
import type { PostListItem } from "@/lib/api";

interface PostsGridProps {
  posts: PostListItem[];
  hasMore: boolean;
  onLoadMore: () => void;
  isLoading?: boolean;
  loadError?: boolean;
  /** Se true, la griglia può essere vuota perché tutti i post sono in hero (es. categoria con 3 articoli). */
  emptyGridIsExpected?: boolean;
}

export default function PostsGrid({ posts, hasMore, onLoadMore, isLoading, loadError, emptyGridIsExpected }: PostsGridProps) {
  if (posts.length === 0) {
    if (hasMore) {
      return (
        <section>
          <div className="mt-8 flex justify-center">
            <button
              type="button"
              onClick={onLoadMore}
              disabled={isLoading}
              className="min-h-11 px-6 py-3 bg-accent text-gray-900 font-semibold rounded hover:opacity-90 disabled:opacity-60 transition-opacity focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background"
            >
              {isLoading ? "Caricamento..." : loadError ? "Riprova" : "Carica altri articoli"}
            </button>
          </div>
        </section>
      );
    }
    if (!hasMore && !emptyGridIsExpected) {
      return (
        <p className="text-muted py-8 text-center">Nessun articolo trovato.</p>
      );
    }
    return null;
  }

  return (
    <section>
      <p className="sr-only" role="status" aria-live="polite">
        {isLoading
          ? "Caricamento di altri articoli in corso"
          : loadError
            ? "Impossibile caricare altri articoli. Puoi riprovare."
            : ""}
      </p>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8">
        {posts.map((post, index) => (
          <ArticleCard key={post.id} post={post} priority={index === 0} />
        ))}
        {posts.length % 2 !== 0 && <div className="hidden md:block" aria-hidden />}
      </div>
      {hasMore && (
        <div className="mt-8 flex justify-center">
          <button
            type="button"
            onClick={onLoadMore}
            disabled={isLoading}
            className="min-h-11 px-6 py-3 bg-accent text-gray-900 font-semibold rounded hover:opacity-90 disabled:opacity-60 transition-opacity focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background"
          >
            {isLoading ? "Caricamento..." : loadError ? "Riprova" : "Carica altri articoli"}
          </button>
        </div>
      )}
    </section>
  );
}
